using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions { TypeInfoResolver = new DefaultJsonTypeInfoResolver() };

// 1. Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// 2. Probe without throwing — TryGetTypeInfo returns false instead of throwing
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

// Probe for a type whose metadata might NOT be available (e.g., with a restricted resolver)
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { ti => { if (ti.Type == typeof(Secret)) throw new NotSupportedException(); } }
    }
};

bool foundSecret = restricted.TryGetTypeInfo(typeof(Secret), out JsonTypeInfo? secretInfo);
Console.WriteLine($"TryGetTypeInfo(Secret) on restricted resolver: found={foundSecret}, info is null={secretInfo is null}");

record Person(string Name, int Age);
record Secret(string Value);
EOF
