using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions { TypeInfoResolver = new DefaultJsonTypeInfoResolver() };

// 1. Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// 2. Probe without throwing — TryGetTypeInfo returns false if resolver yields null
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

// Use a resolver that only knows about Person — Secret is unknown
var selective = new JsonSerializerOptions
{
    TypeInfoResolver = new SelectiveResolver()
};

bool foundSecret = selective.TryGetTypeInfo(typeof(Secret), out JsonTypeInfo? secretInfo);
Console.WriteLine($"TryGetTypeInfo(Secret) on selective resolver: found={foundSecret}, info is null={secretInfo is null}");

// Show that the same resolver *does* find Person
bool foundPerson = selective.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pi);
Console.WriteLine($"TryGetTypeInfo(Person) on selective resolver: found={foundPerson}");

record Person(string Name, int Age);
record Secret(string Value);

// A resolver that only provides metadata for Person
class SelectiveResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person)) return _inner.GetTypeInfo(type, options);
        return null; // signals "not available" — TryGetTypeInfo returns false
    }
}
EOF
